const esc = (v) => String(v == null ? '' : v).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const button = (url, label) => '<p style="margin:22px 0"><a href="' + esc(url) + '" style="display:inline-block;background:#e11d48;color:#ffffff;text-decoration:none;padding:14px 26px;border-radius:12px;font-weight:700;font-size:16px">' + esc(label) + '</a></p>';
const layout = (title, bodyHtml, unsubscribeUrl) =>
  '<div style="font-family:system-ui,Segoe UI,Roboto,Arial,sans-serif;max-width:520px;margin:auto;color:#0f172a">' +
  '<h2 style="color:#e11d48;margin:0 0 6px">' + esc(title) + '</h2>' + bodyHtml +
  '<p style="color:#64748b;font-size:13px;margin-top:22px">Need help? Just reply to this email or message us on WhatsApp. 💚<br>— Team FluxFilm</p>' +
  (unsubscribeUrl ? '<p style="color:#94a3b8;font-size:11px;margin-top:18px">Don\'t want these emails? <a href="' + esc(unsubscribeUrl) + '" style="color:#94a3b8">Unsubscribe</a></p>' : '') +
  '</div>';

const x = $json;
const name = esc(x.greetingName || 'there');
const svc = esc(x.lastService);
let subject, title, body;
if (x.campaign === 'WB15') {
  subject = '🎁 ' + (x.greetingName && x.greetingName !== 'there' ? x.greetingName + ', ' : '') + 'a little gift to come back — ' + x.offer;
  title = 'Kaafi din ho gaye! 👋';
  body = '<p>Hi ' + name + ',</p><p>Your <b>' + svc + '</b> plan ended on ' + esc(x.lastEndedText) + '. New shows and movies are waiting for you. 🍿</p>' +
    '<p>Here is a <b>personal coupon</b> just for you: <b style="font-size:18px;letter-spacing:1px">' + esc(x.couponCode) + '</b> — <b>' + esc(x.offer) + '</b>, valid till ' + esc(x.couponExpiryText) + '.</p>' +
    '<p>Tap the button, the coupon is filled in for you.</p>';
} else {
  subject = '💜 We miss you at FluxFilm — ' + x.offer + ' inside';
  title = 'Wapas aa jao! 🎬';
  body = '<p>Hi ' + name + ',</p><p>It\'s been a month since your <b>' + svc + '</b> plan ended. We saved a <b>bigger welcome-back offer</b> for you:</p>' +
    '<p style="background:#fff1f2;border:1px dashed #e11d48;border-radius:12px;padding:12px 14px;font-size:15px">🎟️ <b>' + esc(x.couponCode) + '</b> — ' + esc(x.offer) + '<br><span style="color:#64748b">Only for your number · one use · till ' + esc(x.couponExpiryText) + '</span></p>' +
    '<p>Works on any plan, new or renewal.</p>';
}
return { json: Object.assign({}, x, { subject, html: layout(title, body + button(x.buyUrl || x.shopUrl, 'Use my coupon'), x.unsubscribeUrl) }) };
